UPDATE creation
SET title = #{title}, content = #{content}
WHERE id = #{id} AND user_id = #{userId}

UPDATE creation
SET state = #{state},
    published_at = CASE WHEN #{state} = 'PUBLISHED' THEN #{publishedAt}
                        ELSE published_at END
WHERE id = #{id} AND user_id = #{userId}

